function shortestPaths(graph, s, t) {
  const N = graph.length;
  const dist = Array(N).fill(Infinity);
  const ways = Array(N).fill(0);
  dist[s] = 0;
  ways[s] = 1;
  const pq = new MinHeap((a,b)=>a.d-b.d);
  pq.push({node:s, d:0});
  while (!pq.isEmpty()) {
     const {node:u, d} = pq.pop();
     if (d !== dist[u]) continue;
     for (const [v, w] of graph[u]) {
        const nd = dist[u] + w;
        if (nd < dist[v]) { dist[v] = nd; ways[v] = ways[u]; pq.push({node:v, d:nd}); }
        else if (nd === dist[v]) { ways[v] += ways[u]; }
     }
  }
  return { dist: dist[t], count: ways[t] };
}
```

