## Why This Is Asked

Assesses ability to design a stable multi-key sort and apply bit-operations in a practical setting.

## Key Concepts

- Stable sort
- Two-key comparator
- Hamming weight (popcount)
- Time/space trade-offs

## Code Example

```javascript
function sortByWeightAndValue(arr) {
  const popcount = (n) => {
    n = n >>> 0;
    n = n - ((n >>> 1) & 0x55555555);
    n = (n & 0x33333333) + ((n >>> 2) & 0x33333333);
    n = (n + (n >>> 4)) & 0x0f0f0f0f;
    return (n * 0x01010101) >>> 24;
  };
  const items = arr.map(v => ({ val: v, w: popcount(v) }));
  const mergeSort = (a) => {
    if (a.length <= 1) return a.slice();
    const m = Math.floor(a.length / 2);
    const L = mergeSort(a.slice(0, m));
    const R = mergeSort(a.slice(m));
    const res = [];
    let i = 0, j = 0;
    while (i < L.length && j < R.length) {
      if (L[i].w !== R[j].w) res.push(L[i].w < R[j].w ? L[i++] : R[j++]);
      else res.push(L[i].val <= R[j].val ? L[i++] : R[j++]);
    }
    while (i < L.length) res.push(L[i++]);
    while (j < R.length) res.push(R[j++]);
    return res;
  };
  const sorted = mergeSort(items);
  return sorted.map(o => o.val);
}
```

## Why This Is Asked

Tests practical DP reasoning: variable step costs require deriving both a memoized and a tabular solution, handle unreachable states, and discuss trade-offs.

## Key Concepts

- Top-down DP with memoization
- Bottom-up DP (tabulation)
- Handling unreachable states with Infinity
- Time/space complexity: O(n|S|) time, O(n) space

## Code Example

```javascript
function minCostTopDown(n, steps, memo=new Map()){
  if(n===0) return 0
  if(n<0) return Infinity
  if(memo.has(n)) return memo.get(n)
  let best = Infinity
  for(let s of steps){
    const c = s + minCostTopDown(n-s, steps, memo)
    if(c < best) best = c
  }
  memo.set(n, best)
  return best
}

function minCostBottomUp(n, steps){
  const INF = Number.POSITIVE_INFINITY
  const dp = Array(n+1).fill(INF)
  dp[0] = 0
  for(let i=1; i<=n; i++){
    for(let s of steps){
      if(i>=s && dp[i-s] !== INF){
        dp[i] = Math.min(dp[i], s + dp[i-s])
      }
    }
  }
  return dp[n] === INF ? -1 : dp[n]
}
```

